"""Every seeded classification rule is a body `POST /rules` would accept.

The same shape `test_seeded_layouts.py` sets, for the same reason: a seed is edited by hand and
applied by hand, and the first thing to notice a rule the endpoint refuses is the owner,
mid-import. A pack dropped into `db/seeds/rules/` is covered on the day it lands.

Two things beyond the shape are checked here because only this file can check them.

**A pack names categories by slug and carries no id.** An id generated by whichever database
loaded the taxonomy is meaningless in another one, exactly as `db/seeds/README.md` says of an
`institutionId` on a layout — and the taxonomy's ids are generated, not fixed.

**No pattern in a pack names an institution, a currency or a country.** The identifier check
guards identifiers in source files; a pattern inside a JSON seed is neither, so the rule that
keeps ADR-0012 true for the pack is asserted here.
"""

from __future__ import annotations

import json
import re
from decimal import Decimal
from pathlib import Path
from typing import Any
from uuid import UUID

import pytest

from oneledger.ingest.classify import Candidate, Knowledge, Rule, classify_row
from oneledger.routes.rules import RuleBody

# Stands in for whatever id the taxonomy has in the database doing the loading.
RESOLVED = UUID(int=1)

ROOT = Path(__file__).resolve().parents[2]
PACKS = sorted((ROOT / "db" / "seeds" / "rules").glob("*.json"))
# V9 creates the shared taxonomy and Flyway checksums it, so the migration is a fixed and
# authoritative list of the slugs a pack may name — and reading it needs no database, which
# means this runs on every push rather than only where one is reachable.
V9 = ROOT / "db" / "migrations" / "V9__categories_and_merchants.sql"


def _seed_slugs() -> set[str]:
    text = V9.read_text()
    roots = set(re.findall(r"^\s*\('[^']*',\s*'([a-z0-9-]+)',\s*'\w+',\s*'\w+',", text, re.M))
    children = set()
    for parent, child in re.findall(
        r"^\s*\('([a-z0-9-]+)',\s*'[^']*',\s*'([a-z0-9-]+)',\s*\d+\)", text, re.M
    ):
        children.add(f"{parent}-{child}")
    return roots | children


SEED_SLUGS = _seed_slugs()

# Names that must never appear in a pack. Read from the identifier check's own vocabulary so
# the two cannot drift: if a name is added there, a pack carrying it starts failing here.
FORBIDDEN = re.compile(
    r"\b(hdfc|axis|citi|icici|sbi|emirates|enbd|noon|skywards|"
    r"inr|aed|usd|eur|gbp|rupee|dirham|dollar|"
    r"india|indian|uae|emirati|dubai|sharjah|abu\s*dhabi)\b",
    re.IGNORECASE,
)


def _pack(path: Path) -> dict[str, Any]:
    values: dict[str, Any] = json.loads(path.read_text())
    return values


def test_the_rules_directory_holds_packs_to_check() -> None:
    """The guard on the guard: a glob that matches nothing parametrizes to nothing and reports
    green, so without this the suite would go on passing after a rename or a move."""
    assert PACKS, f"no rule pack found in {ROOT / 'db' / 'seeds' / 'rules'}"


def test_the_seed_taxonomy_was_actually_read() -> None:
    """And the guard on that guard. An empty slug set would make every slug check vacuous."""
    assert len(SEED_SLUGS) > 100, f"only {len(SEED_SLUGS)} slugs parsed from V9"
    assert "salary-base" in SEED_SLUGS
    assert "financial-bank-charges" in SEED_SLUGS


@pytest.mark.parametrize("path", PACKS, ids=lambda path: path.stem)
def test_every_rule_in_a_pack_is_a_body_the_endpoint_accepts(path: Path) -> None:
    pack = _pack(path)
    assert pack["rules"], f"{path.name} carries no rules"
    for index, rule in enumerate(pack["rules"]):
        # The slug becomes `setCategoryId` when the pack is loaded, so it is substituted here
        # rather than dropped: for most of these rules the category *is* the only outcome, and
        # dropping it would test a body the loader never builds.
        body = {key: value for key, value in rule.items() if key != "setCategorySlug"}
        if "setCategorySlug" in rule:
            body["setCategoryId"] = str(RESOLVED)
        try:
            RuleBody.model_validate(body)
        except Exception as refused:  # the message is the point
            pytest.fail(f"{path.name} rule {index} ({rule.get('name')}): {refused}")


@pytest.mark.parametrize("path", PACKS, ids=lambda path: path.stem)
def test_a_pack_names_categories_by_slug_and_carries_no_id(path: Path) -> None:
    for rule in _pack(path)["rules"]:
        assert "setCategoryId" not in rule, f"{rule.get('name')} carries a category id"
        assert "setMerchantId" not in rule, f"{rule.get('name')} carries a merchant id"
        assert "matchAccountId" not in rule, f"{rule.get('name')} carries an account id"
        assert "setCounterpartyAccountId" not in rule


@pytest.mark.parametrize("path", PACKS, ids=lambda path: path.stem)
def test_every_slug_a_pack_names_is_one_the_seed_taxonomy_defines(path: Path) -> None:
    for rule in _pack(path)["rules"]:
        slug = rule.get("setCategorySlug")
        if slug is None:
            continue
        assert slug in SEED_SLUGS, f"{rule.get('name')} names {slug!r}, which V9 does not create"


@pytest.mark.parametrize("path", PACKS, ids=lambda path: path.stem)
def test_no_pack_names_an_institution_a_currency_or_a_country(path: Path) -> None:
    """ADR-0012 for the half `scripts/check-identifiers.py` cannot see."""
    for rule in _pack(path)["rules"]:
        for key in ("name", "matchDescriptionPattern", "matchReferencePattern"):
            value = rule.get(key)
            if value is None:
                continue
            found = FORBIDDEN.search(value)
            assert found is None, (
                f"{rule.get('name')}: {key} names {found.group(0)!r}. A pack describes what a "
                "bank writes about itself, never which bank wrote it (ADR-0012)."
            )
        assert rule.get("matchCurrency") is None, "a pack must not key on a currency"
        assert rule.get("matchCountry") is None, "a pack must not key on a country"
        assert rule.get("setCountry") is None


@pytest.mark.parametrize("path", PACKS, ids=lambda path: path.stem)
def test_a_pack_leaves_room_above_it_for_the_household_s_own_rules(path: Path) -> None:
    """A user rule beats a seed rule by being an earlier cascade step, and the priorities agree
    with that rather than contradicting it — a seed rule numbered below the user default would
    read, to anyone scanning the list, as outranking rules it can never outrank."""
    for rule in _pack(path)["rules"]:
        priority = rule.get("priority", 100)
        assert priority > 100, f"{rule.get('name')} sits at {priority}, at or above user rules"


@pytest.mark.parametrize(
    ("description", "amount", "expected_type"),
    [
        ("PREMIER CAFE", "-10", None),
        ("REMITTANCE OUTWARD", "-10", None),
        ("EMILY MARKET", "-10", None),
        ("CHEMICAL SUPPLIES", "-10", None),
        ("éEMIé SHOP", "-10", None),
        ("漢EMI字 SHOP", "-10", None),
        ("EMÍLY MARKET", "-10", None),
        ("EMI\u0301LY MARKET", "-10", None),
        ("E\u0301EMI CAFE", "-10", None),
        ("EMI\u093e SHOP", "-10", None),
        ("LOAN EMI PAYMENT", "10", None),
        ("LOAN EMI PAYMENT", "-10", "loan_repayment"),
        ("EMI COLLECTION", "-10", "loan_repayment"),
        ("emi (2/12)", "-10", "loan_repayment"),
        ("EMI", "-10", "loan_repayment"),
        ("ACH-DR-EMI-COLLECTION", "-10", "loan_repayment"),
        ("PAYMENT:EMI/INSTALMENT", "-10", "loan_repayment"),
        ("LOAN\u00a0EMI\u00a0PAYMENT", "-10", "loan_repayment"),
    ],
)
def test_loan_seed_requires_a_debit_and_a_whole_token(
    description: str, amount: str, expected_type: str | None
) -> None:
    """A substring match wrongly hides purchases from reporting as loan repayments."""
    raw = next(
        rule for path in PACKS for rule in _pack(path)["rules"] if rule["name"] == "Loan instalment"
    )
    rule = Rule(
        id=RESOLVED,
        priority=raw["priority"],
        origin="seed",
        match_description_pattern=raw["matchDescriptionPattern"],
        match_pattern_kind=raw.get("matchPatternKind", "contains"),
        match_direction=raw.get("matchDirection", "any"),
        set_category_id=RESOLVED,
        set_txn_type=raw["setTxnType"],
    )
    candidate = Candidate(
        account_id=RESOLVED,
        description_clean=description,
        amount=Decimal(amount),
        currency="XXX",
    )
    answer = classify_row(candidate, Knowledge(seed_rules=[rule]))
    assert answer.txn_type == expected_type
    assert answer.classified_by == ("seed_rule" if expected_type else "unclassified")
